{#- Code generated by authfly/codegen from specs/widgets/notice.def.ts. DO NOT EDIT.
    Authfly notice on UI8Kit 3 primitives: check email, verified, link error, sign out (form). Props as xgen. -#}
{%- import 'authfly/components.html.twig' as af -%}
{%- set id = p.id ?? '' -%}{%- set l = p.labels ?? {} -%}{%- set error = p.error ?? '' -%}
{%- set formError = error ? id ~ '-error' : null -%}
{%- set isError = (p.tone ?? 'default') == 'error' -%}
{%- set c3 -%}
{{ af.icon_badge(p.icon ?? 'mail-check', isError ? 'destructive' : 'default') }}
{%- set c1 -%}{%- if p.detail ?? '' -%}
{{ af.text('', 'text-sm font-semibold text-foreground', {'data-testid': 'detail'}, af_esc(p.detail ?? '')) }}
{%- endif -%}{%- endset -%}
{{ af.head(id, p.title ?? '', p.text ?? '', 'center', isError ? 'alert' : 'status', c1) }}
{%- if (p.action ?? 'link') == 'form' -%}
{%- set c2 -%}{{ af.hidden('csrf', p.csrf ?? '') }}
{{ af.button('', 'submit', af_skin('button', 'default', 'w-full'), {'data-testid': 'submit'}, af_esc(l.cta ?? '')) }}{%- endset -%}
{{ af.form(p.actionUrl ?? '', 'w-full', {'data-testid': 'authfly-form'}, c2) }}
{%- else -%}
{{ af.button(l.ctaHref ?? '', '', af_skin('button', 'default', 'w-full'), {'data-testid': 'cta'}, af_esc(l.cta ?? '')) }}
{%- endif -%}
{%- if l.secondary ?? '' -%}
{{ af.link(l.secondaryHref ?? '', af_skin('link', 'text-sm'), 'secondary', l.secondary ?? '') }}
{%- endif -%}
{%- endset -%}
{{ af.card(af_skin('widgetCard', 'items-center text-center'), {'data-testid': 'authfly-notice', 'data-tone': p.tone ?? 'default'}|merge({'aria-labelledby': (p.landmarkLabel ?? '') ? null : id ~ '-title', 'aria-label': p.landmarkLabel ?? null}), c3) }}
